// Sentinel Aperture mark: contour definition and SVG generation.
// Contours are generated by scripts/generate-mark.mjs into src/assets/monogram-shape.json.
// This module renders that same contour set to raster/vector assets so the 3D geometry
// and the interface icons stay derived from one source of truth.
import polygons from './monogram-shape.json' with { type: 'json' };

// Contours are centred on the origin; 0.35 units of padding keeps bevels and rounded
// corners clear of the viewBox edge.
const pad = 3.05;

function contourPath(points) {
  return points.map(([x, y], index) => `${index ? 'L' : 'M'}${x.toFixed(4)} ${(-y).toFixed(4)}`).join('') + 'Z';
}

export function markPathData() {
  return polygons.map(([outer, ...holes]) => [contourPath(outer), ...holes.map(contourPath)].join('')).join('');
}

export function markViewBox() {
  return `${-pad} ${-pad} ${pad * 2} ${pad * 2}`;
}

// Keeps the same white-on-black convention the original D monogram used, so the 3D
// shader texture slots and the square social icon can consume it unchanged.
export function markSvg({ size = 512, background = '#000', fill = '#fff' } = {}) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="${markViewBox()}"><rect x="${-pad}" y="${-pad}" width="${pad * 2}" height="${pad * 2}" fill="${background}"/><path fill="${fill}" fill-rule="evenodd" d="${markPathData()}"/></svg>`;
}

export { polygons };